// Pull the sync state saved by the previous run (ETag + watermark) out of
// workflow static data, and carry the config forward on the same item.
const store = $getWorkflowStaticData('global');
const cfg = $('Set Config').first().json;
return [{
  json: {
    repoOwner: cfg.repoOwner,
    repoName: cfg.repoName,
    minFollowers: cfg.minFollowers,
    minPublicRepos: cfg.minPublicRepos,
    minRateRemaining: cfg.minRateRemaining,
    slackWebhookUrl: cfg.slackWebhookUrl,
    stargazersEtag: store.stargazersEtag || '',
    lastStarredAt: store.lastStarredAt || ''
  }
}];

// GitHub returns stargazers oldest-first, so new stars are on the LAST page.
// Read the page count from the RFC-5988 Link header instead of paginating.
// Also surface the primary rate-limit budget for the guard below.
const res = $input.first().json;
const headers = res.headers || {};
const link = headers.link || headers.Link || '';
const m = link.match(/[?&]page=(\d+)>;\s*rel="last"/);
const remaining = parseInt(headers['x-ratelimit-remaining'] ?? '9999', 10);
return [{ json: { lastPage: m ? parseInt(m[1], 10) : 1, rateRemaining: remaining } }];

// Handle the conditional response.
// 304 Not Modified -> nothing starred since last poll, and this response does
// NOT count against the rate limit. Return nothing so the workflow ends here.
const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const status = res.statusCode || 200;

if (status === 304) {
  return [];
}

// Save the new ETag for next run's conditional request.
const headers = res.headers || {};
const newEtag = headers.etag || headers.ETag;
if (newEtag) store.stargazersEtag = newEtag;

const body = Array.isArray(res.body) ? res.body : [];
const prev = store.lastStarredAt ? new Date(store.lastStarredAt) : null;

let newest = prev || new Date(0);
for (const it of body) {
  const t = new Date(it.starred_at);
  if (t > newest) newest = t;
}
store.lastStarredAt = newest.toISOString();

let fresh;
if (prev) {
  fresh = body.filter((it) => new Date(it.starred_at) > prev);
} else {
  fresh = body.slice(-5); // first run: seed the demo
}

return fresh.map((it) => ({
  json: { login: it.user.login, starred_at: it.starred_at }
}));

