// Combine the enriched GitHub profile with the AI pitch into a Slack payload.
const user = $('Enrich: Get User Profile').item.json;
const pitch = ($json.choices?.[0]?.message?.content || '').trim() || '(pitch unavailable)';
const cfg = $('Load Sync State').first().json;
const header = ':dart: New high-value lead starred ' + cfg.repoOwner + '/' + cfg.repoName;

return {
  json: {
    text: header,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: '*' + header + '*' } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: '*Name:*\n' + (user.name || user.login) },
        { type: 'mrkdwn', text: '*Company:*\n' + (user.company || '-') },
        { type: 'mrkdwn', text: '*Followers:*\n' + user.followers },
        { type: 'mrkdwn', text: '*Public repos:*\n' + user.public_repos }
      ] },
      { type: 'section', text: { type: 'mrkdwn', text: '*Bio:*\n' + (user.bio || '-') } },
      { type: 'section', text: { type: 'mrkdwn', text: '*AI sales pitch:*\n' + pitch } },
      { type: 'context', elements: [ { type: 'mrkdwn', text: '<https://github.com/' + user.login + '|github.com/' + user.login + '>' } ] }
    ]
  }
};
